toad_implementation.code_blueprint:
canvas {
  size: 600px 900px;
  fill: #F5F5F3;
  font-family: "Univers, sans-serif";
}

>galleryWall = #F5F5F3;
>basalt = #1A1A1A;
>metaGray = #888888;
>divider = #DCDCDA;

rect #steleFrame {
  at: center of canvas;
  size: 480px 780px;
  fill: #FFFFFF;
  stroke: >divider;
  stroke-width: 1px;
}

text #artistName {
  at: top left of #steleFrame offset 48px 64px;
  content: "ALBERTO GIACOMETTI";
  font-size: 16px;
  font-weight: 500;
  color: >basalt;
}

text #artistDates {
  at: below #artistName offset 6px;
  content: "1901 – 1966, Borgonovo (Schweiz)";
  font-size: 11px;
  color: >metaGray;
}

rect #titleDivider {
  at: below #artistDates offset 24px;
  size: 384px 1px;
  fill: >divider;
}

text #artworkTitle {
  at: below #titleDivider offset 24px;
  content: "L'Homme qui marche I";
  font-size: 22px;
  font-weight: 400;
  color: >basalt;
}

text #artworkDetails {
  at: below #artworkTitle offset 10px;
  size: 384px;
  content: "1960. Bronze, Gussverfahren, Patina.\n182.5 × 27 × 97 cm.\nStiftung Alberto Giacometti, Zürich.\nInv.-Nr. G-1960.01";
  font-size: 12px;
  color: #555555;
}
